-- v1.32.0: payment-provider-ready legal pages (owner: Paystack/Flutterwave review). The company is Luda Digital Systems Limited.
-- New kind 'policy' (Refund & cancellation, AML & KYC, About): public, edited in Luda HQ like the Terms (content:full).
alter table public.guides drop constraint if exists guides_kind_check;
alter table public.guides add constraint guides_kind_check check (kind in ('guide', 'terms', 'tip', 'help', 'privacy', 'policy'));

insert into public.guides (slug, kind, title, intro, steps, updated_by) values ('refunds', 'policy', 'Refund & cancellation policy', 'This policy explains when and how Luda Digital Systems Limited returns money to you. Refunds go back to your Luda wallet unless stated otherwise. To ask for a refund, open Help, then Message us in the app, or email support@useluda.com with your reference.', '[{"title": "Top-ups", "body": "Your wallet is credited when our payment partner (Paystack or Flutterwave) confirms the payment. If you were charged but your wallet was not credited, we check with the partner automatically within 48 hours. If the payment is confirmed we credit it; if not, the partner returns the money to your card or bank account, usually within 5–10 business days. Money already credited to your wallet is not sent back to the card; you can withdraw it to your own bank account instead."}, {"title": "Withdrawals", "body": "If a withdrawal fails or cannot be paid, the full amount and the withdrawal fee go back to your wallet. A withdrawal that has reached your bank cannot be cancelled."}, {"title": "Currency conversion", "body": "A conversion is final once you confirm it at the rate shown. If the rate changes before you confirm, you see the new rate first."}, {"title": "Bus tickets", "body": "Contact us before the travel date to cancel an unused ticket; it is refunded to your wallet. Used tickets, and tickets for a date that has passed, are not refunded."}, {"title": "Bills and rent", "body": "If the Luda team cannot pay your bill, the amount and the fee are refunded to your wallet with the reason. Once a bill is paid and the receipt is added, Luda cannot take it back; mistakes in the details you typed (like a wrong meter number) must be fixed with the biller."}, {"title": "Market and Flash jobs", "body": "Payments are held by Luda until the buyer or poster confirms. If a seller cancels, a helper drops a job, or the Luda team decides a problem in your favour, the held money is refunded to your wallet. Report a problem before the automatic release time."}, {"title": "P2P exchange", "body": "Naira held for a P2P order goes back to the Naira payer if the order is cancelled, runs out of time before the other side marks it sent, or the Luda team decides an appeal that way. Money sent outside Luda (bank transfer or cash) is between the two users; Luda can only decide what happens to the Naira it holds."}, {"title": "Fees", "body": "A fee is refunded when the transaction it belongs to is refunded in full (for example a failed withdrawal or an unpaid bill). Fees charged by payment partners at top-up are set by the partner."}, {"title": "Chargebacks", "body": "Please contact us before disputing a payment with your bank. If you open a chargeback for a top-up you already used in Luda, we may hold your account while we look into it and recover the amount from your wallet."}, {"title": "How long it takes", "body": "We answer refund requests within 2 business days. Refunds to your Luda wallet are instant once approved. Refunds to a card or bank account depend on the payment partner and your bank."}]'::jsonb, 'luda') on conflict (slug) do nothing;
insert into public.guides (slug, kind, title, intro, steps, updated_by) values ('aml', 'policy', 'AML & KYC policy', 'Luda Digital Systems Limited works to stop fraud, money laundering and the financing of crime on Luda. This policy explains the checks we do and what we may do when something looks wrong.', '[{"title": "Knowing our customers", "body": "Every account needs a real name, an email address and a payment PIN. Before you can withdraw, trade P2P, sell on the Market or take paid Flash jobs, you must verify your identity with an official ID document and a live selfie. Checks are done by our partner Didit, or by the Luda team for documents sent to us."}, {"title": "One account per person", "body": "Each person may have only one Luda account. ID documents and faces are compared with other verified accounts, and extra accounts are frozen."}, {"title": "Limits", "body": "Accounts that are not verified have low top-up and balance limits. Verified accounts have higher daily limits for top-ups, withdrawals, sending and conversion. Lira bought with Naira is limited per day and can be spent in Luda but not sent to other people."}, {"title": "Withdrawals", "body": "Money can only be withdrawn to a bank account in the same name as your verified ID. After a password or PIN reset, withdrawals and sending are paused for 24 hours."}, {"title": "Monitoring", "body": "Our server records every movement of money in a ledger. We watch for unusual activity, such as many accounts on one device, payments that don''t match, or patterns linked to scams."}, {"title": "What we may do", "body": "We may ask for more information or documents, delay or refuse a transaction, hold money in escrow, limit or freeze an account, and close accounts used for fraud. Where the law requires it, we report suspicious activity to the authorities, and we may not be allowed to tell you."}, {"title": "Not allowed on Luda", "body": "Money laundering, fraud, scams, using someone else''s identity or account, buying or selling accounts, paying for illegal goods or services, and asking people to pay outside Luda."}, {"title": "Records", "body": "We keep identity check results and transaction records for as long as the law requires, including after an account is closed."}, {"title": "Reporting a concern", "body": "To report suspicious activity, use Report a scam in Help, or email support@useluda.com."}]'::jsonb, 'luda') on conflict (slug) do nothing;
insert into public.guides (slug, kind, title, intro, steps, updated_by) values ('about', 'policy', 'About Luda', 'Luda is an all-in-one app for African students and families living in North Cyprus. It is run by Luda Digital Systems Limited.', '[{"title": "What we offer", "body": "• A wallet in Naira (₦) and Turkish lira (₺): top up by card or bank transfer through Paystack or Flutterwave, and withdraw to your own bank account.\n• Naira ⇄ lira conversion at a rate shown before you confirm.\n• P2P exchange with other verified users, with the Naira held safely by Luda.\n• Bill payments (electricity, water, gas, internet, mobile, rent), paid by the Luda team on the official sites.\n• Girne ⇄ Lefkoşa bus tickets.\n• A marketplace and Flash help jobs, with payment held until the job is done.\n• Free community, housing, jobs and university tools."}, {"title": "Prices", "body": "Creating an account is free and there are no monthly fees. Each paid service has a small fee that you see before you confirm; the full list is on the Fees page. Bus tickets cost ₺250 single and ₺450 return."}, {"title": "How you pay", "body": "Top-ups are paid by card or bank transfer through Paystack, or through Flutterwave for other currencies. After that you pay for everything in the app from your Luda wallet, and you get a receipt for every payment."}, {"title": "When you get it", "body": "Wallet actions happen instantly. Bills are paid within the time shown when you pay, usually within 2 hours during working hours. Bus tickets appear in the app with a QR code for the driver. Market items are handed over between the buyer and the seller."}, {"title": "Contact us", "body": "Help with your account or a payment: support@useluda.com\nGeneral questions: hello@useluda.com\nIn the app: Help, then Message us\nWe answer within 2 business days."}, {"title": "Company", "body": "Luda Digital Systems Limited"}]'::jsonb, 'luda') on conflict (slug) do nothing;

do $$
declare s jsonb; t jsonb := '[]'::jsonb; x jsonb;
begin
  select steps into s from public.guides where slug = 'terms';
  if s is null then return; end if;
  for x in select * from jsonb_array_elements(s) loop
    if x->>'title' = '1. Who we are' then x := jsonb_set(x, '{body}', to_jsonb('Luda is run by Luda Digital Systems Limited. It is an app for students and people from Africa living in North Cyprus. It offers a wallet in Naira and Turkish lira, currency conversion, P2P exchange between users, bill payment help, bus tickets, a marketplace, Flash help jobs, community posts and university tools.'::text));
    elsif x->>'title' = '4. Fees' then x := jsonb_set(x, '{body}', to_jsonb('Fees are shown in the app (Wallet, Fees), on the Fees page (useluda.com/fees) and on every confirmation screen before you approve. Payment partners may add their own fees. We may change fees for future transactions; the fee shown when you confirm is the one that applies.'::text));
    elsif x->>'title' = '13. Changes and contact' then continue;
    end if;
    t := t || jsonb_build_array(x);
  end loop;
  t := t || '[{"title": "13. Refunds, cancellations and chargebacks", "body": "When and how money is returned is explained in our Refund & cancellation policy (useluda.com/refunds), which is part of these terms. If something goes wrong with a payment, contact us first: we answer within 2 business days. If you dispute a card or bank payment with your bank (a chargeback) for money you already used in Luda, we may hold your account while we look into it and recover the amount from your wallet."}, {"title": "14. Identity checks and anti-money-laundering", "body": "We follow our AML & KYC policy (useluda.com/aml). We may ask for more information, limit, hold or refuse a transaction, and report suspicious activity to the authorities where the law requires it."}, {"title": "15. Changes and contact", "body": "We may update these terms; the version and date are shown here, and you will be asked to agree to important changes. Questions or complaints: Help, then Message us in the app, or email support@useluda.com. Company details are on useluda.com/about."}]'::jsonb;
  update public.guides set intro = 'These terms are an agreement between you and Luda Digital Systems Limited ("Luda", "we"), the company that runs the Luda app and useluda.com. By creating an account or using Luda you agree to them. If we change them, we will ask you to agree again before you continue.', steps = t, version = version + 1, updated_at = now(), updated_by = 'luda' where slug = 'terms';
end $$;

do $$
declare s jsonb; t jsonb := '[]'::jsonb; x jsonb;
begin
  select steps into s from public.guides where slug = 'privacy';
  if s is null then return; end if;
  for x in select * from jsonb_array_elements(s) loop
    if x->>'title' = 'Who we share it with' then x := jsonb_set(x, '{body}', to_jsonb('Only the partners needed to run the service: payment providers (Paystack, Flutterwave), our ID check partner (Didit), our email provider and our hosting. We may also share information when the law requires it, for example with the police or a regulator. We never sell your data.'::text)); end if;
    if x->>'title' = 'Your choices' then t := t || '[{"title": "How long we keep it", "body": "Account and transaction records are kept for as long as the law requires for financial records, even after you close your account. Photos you send to support are kept only as long as the case needs them."}, {"title": "How we protect it", "body": "Data travels over encrypted connections. Your PIN and sign-in code are stored only as secure hashes. ID photos and support files are private and visible only to the Luda team members who need them."}]'::jsonb; end if;
    t := t || jsonb_build_array(x);
  end loop;
  update public.guides set intro = 'Luda Digital Systems Limited ("Luda") is responsible for the personal data used in the Luda app and on useluda.com. This notice explains what we collect, why, who we share it with and your choices.', steps = t, updated_at = now(), updated_by = 'luda' where slug = 'privacy';
end $$;
